    }
    fn push(&mut self, hash: u64, values: &[Option<Scalar>]) -> Result<usize, CoreError> {
        if values.len() != self.width || values.iter().any(Option::is_none) {
            return Err(CoreError::protocol("Incomplete safety state"));
        }
        let index = self.links.len();
        self.values.extend(values.iter().flatten().copied());
        self.links.push(self.heads.insert(hash, index));
        Ok(index)
    }
}

fn get_hash(values: &[Option<Scalar>]) -> Result<u64, CoreError> {
    values
        .iter()
        .try_fold(0xcbf2_9ce4_8422_2325_u64, |hash, value| {
            let bits = match value.ok_or_else(|| CoreError::protocol("Incomplete safety state"))? {
                Scalar::Int(value) => u64::from(value as u32) << 1,
                Scalar::Bool(value) => (u64::from(value) << 1) | 1,
                Scalar::Ref(value) => u64::from(value) ^ 0x9e37_79b9_7f4a_7c15,
            };
            Ok(hash.wrapping_mul(0x0000_0100_0000_01b3) ^ bits)
        })
}

struct Search<'a> {
    program: &'a SafetyProgram,
    bounds: SafetyBounds,
    nodes: Vec<Node>,
    store: StateStore,
    result: SafetyResult,
    graph: Option<Vec<Vec<GraphEdge>>>,
    roots: Vec<usize>,
}

impl SafetyProgram {
    pub fn check(&self, bounds: SafetyBounds) -> Result<SafetyResult, CoreError> {
        self.check_with_workers(bounds, 1)
    }
    #[cfg(not(target_arch = "wasm32"))]
    pub fn check_parallel(
        &self,
        bounds: SafetyBounds,
        workers: usize,
    ) -> Result<SafetyResult, CoreError> {
        if workers == 0 || workers > 256 {
            return Err(CoreError::protocol(
                "Safety workers must be between 1 and 256",
            ));
        }
        self.check_with_workers(bounds, workers)
    }
    fn check_with_workers(
        &self,
        bounds: SafetyBounds,
        workers: usize,
    ) -> Result<SafetyResult, CoreError> {
        if self.format != "modelt.safety-program"
            || !matches!(self.version, 1 | 2)
            || self.name.is_empty()
            || self.variables.is_empty()
            || self.variables.len() > 256
            || self.variables.iter().any(String::is_empty)
            || self.variables.iter().collect::<HashSet<_>>().len() != self.variables.len()
            || bounds.max_states == 0
            || bounds.max_work == 0
        {
            return Err(CoreError::protocol("Invalid safety program or bounds"));
        }
        let mut arena = Arena::new(bounds.max_work);
        arena.definitions = self.definitions.as_deref().unwrap_or_default();
        let mut search = Search {
            program: self,
            bounds,
            nodes: vec![],
            graph: (!self.properties.is_empty()).then(Vec::new),
            roots: vec![],
            store: StateStore::new(self.variables.len()),
            result: SafetyResult {
                status: "complete".into(),
                reason: None,
                states: 0,
                generated: 0,
                depth: 0,
                work: 0,
                violation: None,
            },
        };
        let outcome = search.run(&mut arena, workers);
        if let Err(error) = outcome {
            if error.code != "budget" && error.code != "temporal-budget" {
                return Err(error);
            }
            search.result.status = "bounded".into();
            search.result.reason = Some(
                if error.code == "temporal-budget" {
                    "temporal"
                } else {
                    "work"
                }
                .into(),
            );
        }
        search.result.work = arena.work;
        Ok(search.result)
    }
}

impl<'program> Search<'program> {
    fn run(&mut self, arena: &mut Arena<'program>, workers: usize) -> Result<(), CoreError> {
        let program = self.program;
        let metadata = if program.version == 2 {
            Some(std::sync::Arc::new(
                crate::safety_definitions::validate_program(program)?,
            ))
        } else {
            if program.definitions.is_some() {
                return Err(CoreError::protocol("Definitions require safety IR v2"));
            }
            validate_branches(&program.initial, program.variables.len(), 0, 0)?;
            validate_branches(&program.next, program.variables.len(), 1, 0)?;
            None
        };
        arena.metadata = metadata.clone();
        for definition in arena.definitions {
            arena.register_memberships(&definition.body);
        }
        crate::safety_expressions::register_branch_memberships(
            &program.initial,
            &mut |expression| arena.register_memberships(expression),
        );
        crate::safety_expressions::register_branch_memberships(&program.next, &mut |expression| {
            arena.register_memberships(expression)
        });
        for predicate in program.invariants.iter().chain(&program.initial_properties) {
            if metadata.is_none() {
                predicate
                    .expression
                    .validate(program.variables.len(), 2, 0)?;
            }
            arena.register_memberships(&predicate.expression);
            if metadata.as_ref().map_or_else(
                || predicate.expression.is_constant(),
                |metadata| metadata.is_constant(&predicate.expression),
            ) && !predicate
                .expression
                .eval(EvalContext::new(&[], &[]), arena)?
                .boolean()?
            {
                return Err(CoreError::protocol(
                    "Constant invariant or property is false",
                ));
            }
        }
        for predicate in program
            .action_properties
            .iter()
            .chain(&program.action_constraints)
        {
            if metadata.is_none() {
                predicate
                    .expression
                    .validate(program.variables.len(), 1, 0)?;
            }
            arena.register_memberships(&predicate.expression);
        }
        for predicate in &program.constraints {
            if metadata.is_none() {
                predicate
                    .expression
                    .validate(program.variables.len(), 2, 0)?;
            }
            arena.register_memberships(&predicate.expression);
        }
        for property in &program.properties {
            if metadata.is_none() {
                property.formula.validate(program.variables.len(), 0)?;
            }
        }
        for fairness in &program.fairness {
            if metadata.is_none() {
                fairness.validate(program.variables.len(), 0)?;
            }
        }
        for predicate in &program.assumptions {
            if metadata.is_none() {
                predicate
                    .expression
                    .validate(program.variables.len(), 3, 0)?;
            }
            arena.register_memberships(&predicate.expression);
            if !predicate
                .expression
                .eval(EvalContext::new(&[], &[]), arena)?
                .boolean()?
            {
                self.result.status = "assumption-violation".into();
                self.result.violation = Some(SafetyViolation {
                    name: predicate.name.clone(),
                    trace: vec![],
                    loop_start: None,
                    loop_action: None,
                });
                return Ok(());
            }
        }
        let mut next = vec![None; program.variables.len()];
        for (index, branch) in program.initial.iter().enumerate() {
            self.walk(
                arena,
                BranchCursor {
                    definition: branch,
                    index,
                },
                0,
                EvalContext::new(&[], &[]),
                &mut next,
                None,
                &mut false,
            )?;
            if self.stopped() {
                return Ok(());
            }
        }
        if self.nodes.is_empty() {
            self.result.status = "empty".into();
            return Ok(());
        }
        let mut index = 0;
        let mut current = vec![Scalar::Int(0); program.variables.len()];
        #[cfg(not(target_arch = "wasm32"))]
        let mut pool = None;
        #[cfg(not(target_arch = "wasm32"))]
        let parallel = workers > 1 && parallel::is_expensive(program);
        #[cfg(target_arch = "wasm32")]
        let _ = workers;
        while index < self.nodes.len() {
            let end = self.nodes.len();
            #[cfg(not(target_arch = "wasm32"))]
            if parallel
                && end - index >= 16
                && program.action_properties.is_empty()
                && program.properties.is_empty()
                && program.fairness.is_empty()
            {
                if pool.is_none() {
                    pool = Some(parallel::Workers::new(workers, self.store.width)?);
                }
                self.parallel_frontier(index..end, pool.as_mut().unwrap(), arena)?;
                if self.stopped() {
                    return Ok(());
                }
                index = end;
                continue;
            }
            while index < end {
                self.expand(index, arena, &mut current, &mut next)?;
                if self.stopped() {
                    return Ok(());
                }
                index += 1;
            }
        }
        if self.result.status == "complete"
            && let Some(graph) = &mut self.graph
        {
            for (index, edges) in graph.iter_mut().enumerate() {
                edges.push(GraphEdge {
                    target: index,
                    action: None,
                });
            }
            if let Some(violation) = crate::temporal::check(
                program,
                self.bounds,
                &self.store.values,
                self.store.width,
                graph,
                &self.roots,
                arena,
            )? {
                self.result.status = "liveness-violation".into();
                self.result.violation = Some(violation);
            }
        }
        Ok(())
    }
    fn stopped(&self) -> bool {
        self.result.violation.is_some()
            || self.result.reason.as_deref() == Some("work")
            || self.result.reason.as_deref() == Some("states")
    }
    fn expand(
        &mut self,
        index: usize,
        arena: &mut Arena,
        current: &mut [Scalar],
        next: &mut [Option<Scalar>],
    ) -> Result<(), CoreError> {
        let program = self.program;
        current.copy_from_slice(self.store.state(index));
        let mut enabled = false;
        for (branch_index, branch) in program.next.iter().enumerate() {
            self.walk(
                arena,
                BranchCursor {
                    definition: branch,
                    index: branch_index,
                },
                0,
                EvalContext::new(current, &[]),
                next,
                Some(index),
                &mut enabled,
            )?;
            if self.stopped() {
                return Ok(());
            }
        }
        if !enabled && program.check_deadlock {
            self.deadlock(index, arena)?;
        }
        Ok(())
    }
    fn deadlock(&mut self, index: usize, arena: &Arena) -> Result<(), CoreError> {
        self.result.status = "deadlock".into();
        self.result.reason = None;
        self.result.violation = Some(SafetyViolation {
            name: "deadlock".into(),
            trace: self.trace(index, arena)?,
            loop_start: None,
            loop_action: None,
        });
        Ok(())
    }
    #[allow(clippy::too_many_arguments)]
    fn walk(
        &mut self,
        arena: &mut Arena,
        branch: BranchCursor<'_>,
        position: usize,
        context: EvalContext<'_>,
        next: &mut [Option<Scalar>],
        parent: Option<usize>,
        enabled: &mut bool,
    ) -> Result<(), CoreError> {
        visit_branch(
            branch.definition,
            position,
            context,
            next,
            arena,
            &mut |values, arena| {
                *enabled = true;
                self.accept(values, parent, branch.index, arena)?;
                Ok(self.stopped())
            },
        )?;
        Ok(())
    }
    fn accept(
        &mut self,
        values: &[Option<Scalar>],
        parent: Option<usize>,
        action: usize,
        arena: &mut Arena,
    ) -> Result<(), CoreError> {
        let hash = get_hash(values)?;
        self.result.generated += 1;
        if !self.program.constraints.is_empty()
            || (parent.is_some() && !self.program.action_constraints.is_empty())
        {
            let current: Vec<_> = values.iter().flatten().copied().collect();
            let mut in_model = true;
            for predicate in &self.program.constraints {
                if !predicate
                    .expression
                    .eval(EvalContext::new(&current, &[]), arena)?
                    .boolean()?
                {
                    in_model = false;
                    break;
                }
            }
            if in_model && let Some(parent) = parent {
                for predicate in &self.program.action_constraints {
                    if !predicate
                        .expression
                        .eval(EvalContext::new(self.store.state(parent), values), arena)?
                        .boolean()?
                    {
                        in_model = false;
                        break;
                    }
                }
            }
            if !in_model {
                if parent.is_some_and(|index| self.nodes[index].depth >= self.bounds.max_depth) {
                    self.result.status = "bounded".into();
                    self.result.reason = Some("depth".into());
                    return Ok(());
                }
                if let Some((status, name)) =
                    check_properties(self.program, &current, parent, &self.store, true, arena)?
                {
                    let mut trace = parent
                        .map(|index| self.trace(index, arena))
                        .transpose()?
                        .unwrap_or_default();
                    trace.push(SafetyTraceStep {
                        action: parent.map(|_| self.program.next[action].name.clone()),
                        values: current
                            .iter()
                            .map(|value| arena.portable(*value))
                            .collect::<Result<_, _>>()?,
                    });
                    self.result.status = status.into();
                    self.result.reason = None;
                    self.result.violation = Some(SafetyViolation {
                        name: name.into(),
                        trace,
                        loop_start: None,
                        loop_action: None,
                    });
                }
                return Ok(());
            }
        }
        let existing = self.store.find(hash, values);
        let index = if let Some(index) = existing {
            index
        } else {
            let depth = parent.map_or(0, |index| self.nodes[index].depth + 1);
            if depth > self.bounds.max_depth {
                self.result.status = "bounded".into();
                self.result.reason = Some("depth".into());
                return Ok(());
            }
            if self.nodes.len() == self.bounds.max_states as usize {
                self.result.status = "bounded".into();
                self.result.reason = Some("states".into());
                return Ok(());
            }
            let index = self.store.push(hash, values)?;
            self.nodes.push(Node {
                parent,
                action: parent.map(|_| action),
                depth,
            });
            if let Some(graph) = &mut self.graph {
                graph.push(vec![]);
            }
            self.result.states = self.nodes.len();
            self.result.depth = self.result.depth.max(depth);
            index
        };
        if let Some(parent) = parent {
            if let Some(graph) = &mut self.graph {
                graph[parent].push(GraphEdge {
                    target: index,
                    action: Some(action),
                });
            }
        } else if !self.roots.contains(&index) {
            self.roots.push(index);
        }
        let checks_candidate = (existing.is_none() && !self.program.invariants.is_empty())
            || if parent.is_some() {
                !self.program.action_properties.is_empty()
            } else {
                !self.program.initial_properties.is_empty()
            };
        if checks_candidate
            && let Some((status, name)) = check_properties(
                self.program,
                self.store.state(index),
                parent,
                &self.store,
                existing.is_none(),
                arena,
            )?
        {
            let trace = if let Some(parent) = parent {
                let mut trace = self.trace(parent, arena)?;
                trace.push(SafetyTraceStep {
                    action: Some(self.program.next[action].name.clone()),
                    values: self.portable(index, arena)?,
                });
                trace
            } else {
                self.trace(index, arena)?
            };
            self.result.status = status.into();
            self.result.reason = None;
            self.result.violation = Some(SafetyViolation {
                name: name.into(),
                trace,
                loop_start: None,
                loop_action: None,
            });
        }
        Ok(())
    }
    fn portable(&self, index: usize, arena: &Arena) -> Result<Vec<Value>, CoreError> {
        self.store
            .state(index)
            .iter()
            .map(|value| arena.portable(*value))
            .collect()
    }
    fn trace(&self, mut index: usize, arena: &Arena) -> Result<Vec<SafetyTraceStep>, CoreError> {
        let mut trace = vec![];
        loop {
            let node = &self.nodes[index];
            trace.push(SafetyTraceStep {
                action: node
                    .action
                    .map(|index| self.program.next[index].name.clone()),
                values: self.portable(index, arena)?,
            });
            match node.parent {
                Some(parent) => index = parent,
                None => break,
            }
        }
        trace.reverse();
        Ok(trace)
    }
}

fn check_properties<'a>(
    program: &'a SafetyProgram,
    values: &[Scalar],
    parent: Option<usize>,
    store: &StateStore,
    is_new: bool,
    arena: &mut Arena,
) -> Result<Option<(&'static str, &'a str)>, CoreError> {
    if is_new {
        for predicate in &program.invariants {
            if !predicate
                .expression
                .eval(EvalContext::new(values, &[]), arena)?
                .boolean()?
            {
                return Ok(Some(("invariant-violation", &predicate.name)));
            }
        }
    }
    if let Some(parent) = parent {
        if program.action_properties.is_empty() {
            return Ok(None);
        }
        let parent = store.state(parent);
        let next: Vec<_> = values.iter().copied().map(Some).collect();
        for predicate in &program.action_properties {
            if !predicate
                .expression
                .eval(EvalContext::new(parent, &next), arena)?
                .boolean()?
            {
                return Ok(Some(("property-violation", &predicate.name)));
            }
        }
    } else {
        for predicate in &program.initial_properties {
            if !predicate
                .expression
                .eval(EvalContext::new(values, &[]), arena)?
                .boolean()?
            {
                return Ok(Some(("property-violation", &predicate.name)));
            }
        }
    }
    Ok(None)
}

#[cfg(test)]
mod tests {
    use super::{Scalar, StateStore};

    #[test]
    fn colliding_hashes_keep_distinct_typed_states() {
        let mut store = StateStore::new(2);
        let first = [Some(Scalar::Int(0)), Some(Scalar::Int(1))];
        let second = [Some(Scalar::Int(0)), Some(Scalar::Int(2))];
        let third = [Some(Scalar::Bool(false)), Some(Scalar::Int(1))];
        for values in [&first, &second, &third] {
            store.push(0, values).unwrap();
        }
        assert_eq!(store.find(0, &first), Some(0));
        assert_eq!(store.find(0, &second), Some(1));
        assert_eq!(store.find(0, &third), Some(2));
        assert_eq!(
            store.find(0, &[Some(Scalar::Int(0)), Some(Scalar::Int(3))]),
            None
        );
        assert_eq!(store.find(0, &first[..1]), None);
        assert!(store.push(0, &[Some(Scalar::Int(0)), None]).is_err());
        assert_eq!(store.find(0, &third), Some(2));
    }
}

use crate::CoreError;
use crate::ir::{
    Expression, SafetyBounds, SafetyProgram, SafetyTraceStep, SafetyViolation, Scalar,
    TemporalFormula,
};
use crate::safety_expressions::{
    CallFrame, EvalContext, validate_constant_bindings, visit_bindings,
};
use crate::safety_values::Arena;
use std::collections::{HashMap, HashSet, VecDeque};
use std::sync::Arc;

impl TemporalFormula {
    pub(crate) fn validate(&self, variables: usize, depth: usize) -> Result<(), CoreError> {
        self.validate_locals(variables, depth, 0)
    }
    fn validate_locals(
        &self,
        variables: usize,
        depth: usize,
        locals: usize,
    ) -> Result<(), CoreError> {
        if depth > 40 {
            return Err(CoreError::protocol("Temporal formula nesting exceeds 40"));
        }
        match self {
            Self::Frame { .. } => {
                return Err(CoreError::protocol(
                    "Operator references require safety IR v2",
                ));
            }
            Self::Atom { expression } => expression.validate_locals(variables, 1, locals)?,
            Self::Not { formula } | Self::Always { formula } | Self::Eventually { formula } => {
                formula.validate_locals(variables, depth + 1, locals)?
            }
            Self::And { left, right } | Self::Or { left, right } => {
                left.validate_locals(variables, depth + 1, locals)?;
                right.validate_locals(variables, depth + 1, locals)?;
            }
            Self::Forall { bounds, formula } | Self::Exists { bounds, formula } => {
                let locals = validate_constant_bindings(bounds, variables, locals)?;
                formula.validate_locals(variables, depth + 1, locals)?;
            }
        }
        Ok(())
    }
}
#[derive(Clone, Copy)]
pub(crate) struct GraphEdge {
    pub target: usize,
    pub action: Option<usize>,
}

struct LexicalSnapshot {
    locals: Vec<Scalar>,
    frame: Option<Arc<CallFrame>>,
    old: Option<Scalar>,
}

enum Formula<'a> {
    True,
    False,
    Atom(&'a Expression, bool, LexicalSnapshot),
    And(usize, usize),
    Or(usize, usize),
    Until(usize, usize),
    Release(usize, usize),
}
struct Pool<'a> {
    formulas: Vec<Formula<'a>>,
    until: Vec<usize>,
    frame_sequence: usize,
    entries: Vec<Vec<usize>>,
    active_entries: Vec<usize>,
    lower_entered: HashSet<usize>,
}
impl<'a> Pool<'a> {
    fn add(&mut self, formula: Formula<'a>) -> usize {
        let index = self.formulas.len();
        if matches!(formula, Formula::Until(..)) {
            self.until.push(index);
        }
        self.formulas.push(formula);
        self.entries.push(self.active_entries.clone());
        index
    }
    fn lower(
        &mut self,
        formula: &'a TemporalFormula,
        negative: bool,
        context: EvalContext<'_>,
        entries: &[usize],
        arena: &mut Arena,
    ) -> Result<usize, CoreError> {
        let previous = std::mem::replace(&mut self.active_entries, entries.to_vec());
        let result = self.lower_inner(formula, negative, context, entries, arena);
        self.active_entries = previous;
        result
    }
    fn lower_inner(
        &mut self,
        formula: &'a TemporalFormula,
        negative: bool,
        context: EvalContext<'_>,
        entries: &[usize],
        arena: &mut Arena,
    ) -> Result<usize, CoreError> {
        arena.tick()?;
        Ok(match formula {
            TemporalFormula::Frame {
                arguments,
                captures,
                formula,
                ..
            } => {
                let frame = CallFrame::new(arguments, captures, context);
                let mut entries = entries.to_vec();
                entries.push(self.frame_sequence);
                self.frame_sequence += 1;
                self.lower(
                    formula,
                    negative,
                    EvalContext {
                        locals: &[],
                        frame: Some(&frame),
                        old: None,
                        ..context
                    },
                    &entries,
                    arena,
                )?
            }
            TemporalFormula::Atom { expression } => self.add(Formula::Atom(
                expression,
                negative,
                LexicalSnapshot {
                    locals: context.locals.to_vec(),
                    frame: context.frame.cloned().map(Arc::new),
                    old: context.old,
                },
            )),
            TemporalFormula::Not { formula } => {
                self.lower(formula, !negative, context, entries, arena)?
            }
            TemporalFormula::And { left, right } | TemporalFormula::Or { left, right } => {
                let left = self.lower(left, negative, context, entries, arena)?;
                let right = self.lower(right, negative, context, entries, arena)?;
                if matches!(formula, TemporalFormula::And { .. }) != negative {
                    self.add(Formula::And(left, right))
                } else {
                    self.add(Formula::Or(left, right))
                }
            }
            TemporalFormula::Always { formula: inner }
            | TemporalFormula::Eventually { formula: inner } => {
                let child = self.lower(inner, negative, context, entries, arena)?;
                if matches!(formula, TemporalFormula::Eventually { .. }) != negative {
                    let truth = self.add(Formula::True);
                    self.add(Formula::Until(truth, child))
                } else {
                    let falsity = self.add(Formula::False);
                    self.add(Formula::Release(falsity, child))
                }
            }
            TemporalFormula::Forall {
                bounds,
                formula: inner,
            }
            | TemporalFormula::Exists {
                bounds,
                formula: inner,
            } => {
                let conjunction = matches!(formula, TemporalFormula::Forall { .. }) != negative;
                let mut result = self.add(if conjunction {
                    Formula::True
                } else {
                    Formula::False
                });
                for entry in entries {
                    if self.lower_entered.insert(*entry) {
                        arena.consume(1)?;
                    }
                }
                visit_bindings(bounds, 0, context, arena, &mut |ctx, arena| {
                    let child = self.lower(inner, negative, ctx, entries, arena)?;
                    result = self.add(if conjunction {
                        Formula::And(result, child)
                    } else {
                        Formula::Or(result, child)
                    });
                    Ok(true)
                })?;
                result
            }
        })
    }
}
#[derive(Clone)]
struct Expansion {
    todo: Vec<usize>,
    seen: HashSet<usize>,
    entered: HashSet<usize>,
    next: Vec<usize>,
    pending: Vec<usize>,
}
struct Alternative {
    next: Vec<usize>,
    pending: Vec<usize>,
}
fn expand(
    pool: &Pool<'_>,
    required: &[usize],
    ctx: EvalContext<'_>,
    arena: &mut Arena,
) -> Result<Vec<Alternative>, CoreError> {
    let mut stack = vec![Expansion {
        todo: required.to_vec(),
        seen: HashSet::new(),
        entered: HashSet::new(),
        next: vec![],
        pending: vec![],
    }];
    let mut result = vec![];
    'alternative: while let Some(mut state) = stack.pop() {
        while let Some(id) = state.todo.pop() {
            arena.tick()?;
            if !state.seen.insert(id) {
                continue;
            }
            for entry in &pool.entries[id] {
                if state.entered.insert(*entry) {
                    arena.consume(1)?;
                }
            }
            match &pool.formulas[id] {
                Formula::True => {}
                Formula::False => continue 'alternative,
                Formula::Atom(expression, negative, lexical) => {
                    if expression
                        .eval(
                            EvalContext {
                                locals: &lexical.locals,
                                frame: lexical.frame.as_deref(),
                                old: lexical.old,
                                ..ctx
                            },
                            arena,
                        )?
                        .boolean()?
                        == *negative
                    {
                        continue 'alternative;
                    }
                }
                Formula::And(left, right) => {
                    state.todo.push(*right);
                    state.todo.push(*left);
                }
                Formula::Or(left, right) => {
                    let mut other = state.clone();
                    other.todo.push(*right);
                    stack.push(other);
                    state.todo.push(*left);
                }
                Formula::Until(left, right) => {
                    let mut other = state.clone();
                    other.todo.push(*left);
                    other.next.push(id);
                    other.pending.push(id);
                    stack.push(other);
                    state.todo.push(*right);
                }
                Formula::Release(left, right) => {
                    let mut other = state.clone();
                    other.todo.push(*right);
                    other.next.push(id);
                    stack.push(other);
                    state.todo.push(*right);
                    state.todo.push(*left);
                }
            }
        }
        state.next.sort_unstable();
        state.next.dedup();
        state.pending.retain(|id| match pool.formulas[*id] {
            Formula::Until(_, right) => !state.seen.contains(&right),
            _ => false,
        });
        state.pending.sort_unstable();
        state.pending.dedup();
        result.push(Alternative {
            next: state.next,
            pending: state.pending,
        });
    }
    Ok(result)
}
#[derive(Clone)]
struct ProductEdge {
    target: usize,
    action: Option<usize>,
    pending: Vec<usize>,
}
struct ProductNode {
    state: usize,
    required: Vec<usize>,
    parent: Option<(usize, usize)>,
}
struct Cycle {
    entry: usize,
    edges: Vec<(usize, usize)>,
}
struct Product<'a> {
    pool: Pool<'a>,
    nodes: Vec<ProductNode>,
    edges: Vec<Vec<ProductEdge>>,
    lookup: HashMap<(usize, Vec<usize>), usize>,
    maximum: usize,
}
impl Product<'_> {
    fn node(
        &mut self,
        state: usize,
        required: Vec<usize>,
        parent: Option<(usize, usize)>,
    ) -> Result<usize, CoreError> {
        if let Some(index) = self.lookup.get(&(state, required.clone())) {
            return Ok(*index);
        }
        if self.nodes.len() == self.maximum {
            return Err(CoreError {
                code: "temporal-budget",
                message: "Temporal product node budget exhausted".into(),
            });
        }
        let index = self.nodes.len();
        self.lookup.insert((state, required.clone()), index);
        self.nodes.push(ProductNode {
            state,
            required,
            parent,
        });
        self.edges.push(vec![]);
        Ok(index)
    }
    fn components(&self, arena: &mut Arena) -> Result<Vec<Vec<usize>>, CoreError> {
        let mut visited = vec![false; self.nodes.len()];
        let mut order = vec![];
        for root in 0..self.nodes.len() {
            if visited[root] {
                continue;
            }
            visited[root] = true;
            let mut stack = vec![(root, 0)];
            while let Some((node, position)) = stack.last_mut() {
                arena.tick()?;
                if let Some(edge) = self.edges[*node].get(*position) {
                    *position += 1;
                    if !visited[edge.target] {
                        visited[edge.target] = true;
                        stack.push((edge.target, 0));
                    }
                } else {
                    order.push(*node);
                    stack.pop();
                }
            }
        }
        let mut reverse = vec![vec![]; self.nodes.len()];
        for (source, edges) in self.edges.iter().enumerate() {
            for edge in edges {
                arena.tick()?;
                reverse[edge.target].push(source);
            }
        }
        visited.fill(false);
        let mut components = vec![];
        for root in order.into_iter().rev() {
            if visited[root] {
                continue;
            }
            visited[root] = true;
            let mut component = vec![];
            let mut stack = vec![root];
            while let Some(node) = stack.pop() {
                arena.tick()?;
                component.push(node);
                for parent in &reverse[node] {
                    if !visited[*parent] {
                        visited[*parent] = true;
                        stack.push(*parent);
                    }
                }
            }
            component.sort_unstable();
            components.push(component);
        }
        Ok(components)
    }
    fn path(
        &self,
        start: usize,
        end: usize,
        members: &HashSet<usize>,
        arena: &mut Arena,
    ) -> Result<Vec<(usize, usize)>, CoreError> {
        if start == end {
            return Ok(vec![]);
        }
        let mut queue = VecDeque::from([start]);
        let mut parents = HashMap::from([(start, None)]);
        while let Some(source) = queue.pop_front() {
            arena.tick()?;
            for (index, edge) in self.edges[source].iter().enumerate() {
                if members.contains(&edge.target) && !parents.contains_key(&edge.target) {
                    parents.insert(edge.target, Some((source, index)));
                    if edge.target == end {
                        let mut path = vec![];
                        let mut node = end;
                        while let Some(Some((source, index))) = parents.get(&node) {
                            path.push((*source, *index));
                            node = *source;
                        }
                        path.reverse();
                        return Ok(path);
                    }
                    queue.push_back(edge.target);
                }
            }
        }
        Err(CoreError::protocol("Broken temporal component"))
    }
    fn accepting_cycle(&self, arena: &mut Arena) -> Result<Option<Cycle>, CoreError> {
        for component in self.components(arena)? {
            let entry = component[0];
            let members: HashSet<_> = component.iter().copied().collect();
            if component.len() == 1 && !self.edges[entry].iter().any(|edge| edge.target == entry) {
                continue;
            }
            let mut selected = vec![];
            let mut accepting = true;
            for until in &self.pool.until {
                let mut witness = None;
                'find: for source in &component {
                    for (index, edge) in self.edges[*source].iter().enumerate() {
                        arena.tick()?;
                        if members.contains(&edge.target) && !edge.pending.contains(until) {
                            witness = Some((*source, index));
                            break 'find;
                        }
                    }
                }
                if let Some(edge) = witness {
                    selected.push(edge);
                } else {
                    accepting = false;
                    break;
                }
            }
            if !accepting {
                continue;
            }
            if selected.is_empty() {
                let Some(index) = self.edges[entry]
                    .iter()
                    .position(|edge| members.contains(&edge.target))
                else {
                    continue;
                };
                selected.push((entry, index));
            }
            let mut current = entry;
            let mut cycle = vec![];
            for (source, index) in selected {
                cycle.extend(self.path(current, source, &members, arena)?);
                cycle.push((source, index));
                current = self.edges[source][index].target;
            }
            cycle.extend(self.path(current, entry, &members, arena)?);
            return Ok(Some(Cycle {
                entry,
                edges: cycle,
            }));
        }
        Ok(None)
    }
}

#[allow(clippy::too_many_arguments)]
pub(crate) fn check(
    program: &SafetyProgram,
    bounds: SafetyBounds,
    values: &[Scalar],
    width: usize,
    graph: &[Vec<GraphEdge>],
    roots: &[usize],
    arena: &mut Arena,
) -> Result<Option<SafetyViolation>, CoreError> {
    for property in &program.properties {
        let mut pool = Pool {
            formulas: vec![],
            until: vec![],
            frame_sequence: 0,
            entries: vec![],
            active_entries: vec![],
            lower_entered: HashSet::new(),
        };
        let mut root = pool.lower(
            &property.formula,
            true,
            EvalContext::new(&[], &[]),
            &[],
            arena,
        )?;
        for fairness in &program.fairness {
            let fairness = pool.lower(fairness, false, EvalContext::new(&[], &[]), &[], arena)?;
            root = pool.add(Formula::And(fairness, root));
        }
        if matches!(pool.formulas[root], Formula::False) {
            return Err(CoreError::protocol(
                "Temporal formula is a tautology (its negation is unsatisfiable)",
            ));
        }
        let mut product = Product {
            pool,
            nodes: vec![],
            edges: vec![],
            lookup: HashMap::new(),
            maximum: bounds.max_temporal_nodes.unwrap_or(bounds.max_states) as usize,
        };
        for state in roots {
            product.node(*state, vec![root], None)?;
        }
        let mut index = 0;
        while index < product.nodes.len() {
            arena.tick()?;
            let source = product.nodes[index].state;
            let required = product.nodes[index].required.clone();
            for edge in &graph[source] {
                let current = &values[source * width..(source + 1) * width];
                let next: Vec<_> = values[edge.target * width..(edge.target + 1) * width]
                    .iter()
                    .copied()
                    .map(Some)
                    .collect();
                for alternative in expand(
                    &product.pool,
                    &required,
                    EvalContext::new(current, &next),
                    arena,
                )? {
                    arena.tick()?;
                    let ordinal = product.edges[index].len();
                    let target =
                        product.node(edge.target, alternative.next, Some((index, ordinal)))?;
                    product.edges[index].push(ProductEdge {
                        target,
                        action: edge.action,
                        pending: alternative.pending,
                    });
                }
            }
            index += 1;
        }
        if let Some(cycle) = product.accepting_cycle(arena)? {
            let entry = cycle.entry;
            let cycle = cycle.edges;
            let mut prefix = vec![];
            let mut current = entry;
            while let Some((source, index)) = product.nodes[current].parent {
                prefix.push((source, index));
                current = source;
            }
            prefix.reverse();
            let mut trace = vec![SafetyTraceStep {
                action: None,
                values: values[product.nodes[current].state * width
                    ..(product.nodes[current].state + 1) * width]
                    .iter()
                    .map(|value| arena.portable(*value))
                    .collect::<Result<_, _>>()?,
            }];
            let label = |action: Option<usize>| {
                action
                    .map(|index| program.next[index].name.clone())
                    .unwrap_or_else(|| "<stuttering>".into())
            };
            for (source, index) in &prefix {
                let edge = &product.edges[*source][*index];
                let state = product.nodes[edge.target].state;
                trace.push(SafetyTraceStep {
                    action: Some(label(edge.action)),
                    values: values[state * width..(state + 1) * width]
                        .iter()
                        .map(|value| arena.portable(*value))
                        .collect::<Result<_, _>>()?,
                });
            }
            let loop_start = trace.len() - 1;
            for (source, index) in cycle.iter().take(cycle.len() - 1) {
                let edge = &product.edges[*source][*index];
                let state = product.nodes[edge.target].state;
                trace.push(SafetyTraceStep {
                    action: Some(label(edge.action)),
                    values: values[state * width..(state + 1) * width]
                        .iter()
                        .map(|value| arena.portable(*value))
                        .collect::<Result<_, _>>()?,
                });
            }
            let (source, index) = cycle[cycle.len() - 1];
            return Ok(Some(SafetyViolation {
                name: property.name.clone(),
                trace,
                loop_start: Some(loop_start),
                loop_action: Some(label(product.edges[source][index].action)),
            }));
        }
    }
    Ok(None)
}

use super::Search;
use crate::CoreError;
use crate::ir::{SafetyProgram, Scalar, Step};
use crate::safety_expressions::{EvalContext, visit_branch};
use crate::safety_values::{Arena, ValueDelta};
use crate::safety_work::WorkBudget;
use rayon::iter::{
    IndexedParallelIterator, IntoParallelIterator, IntoParallelRefMutIterator, ParallelIterator,
};
use std::ops::Range;

enum Event {
    Candidate {
        parent: usize,
        action: usize,
        start: usize,
    },
    Deadlock(usize),
    Error(CoreError),
}

#[derive(Default)]
struct Candidates {
    events: Vec<Event>,
    values: Vec<Option<Scalar>>,
}

impl Candidates {
    fn clear(&mut self) {
        self.events.clear();
        self.values.clear();
    }
    fn push(&mut self, parent: usize, action: usize, values: &[Option<Scalar>]) {
        self.events.push(Event::Candidate {
            parent,
            action,
            start: self.values.len(),
        });
        self.values.extend_from_slice(values);
    }
}

struct Buffer {
    candidates: Candidates,
    next: Vec<Option<Scalar>>,
}

impl Buffer {
    fn new(width: usize) -> Self {
        Self {
            candidates: Candidates::default(),
            next: vec![None; width],
        }
    }
    fn reset(&mut self) {
        self.candidates.clear();
        self.next.fill(None);
    }
}

pub(super) struct Workers {
    pool: rayon::ThreadPool,
    buffers: Vec<Buffer>,
    chunk: usize,
}

impl Workers {
    pub(super) fn new(workers: usize, width: usize) -> Result<Self, CoreError> {
        Ok(Self {
            pool: rayon::ThreadPoolBuilder::new()
                .num_threads(workers)
                .build()
                .map_err(|error| CoreError::protocol(&format!("Safety worker pool: {error}")))?,
            buffers: (0..workers).map(|_| Buffer::new(width)).collect(),
            chunk: 64,
        })
    }
}

impl Workers {
    fn observe(&mut self, parents: usize, candidates: usize) {
        self.chunk = (1024 * parents / candidates.max(1)).clamp(16, 128);
    }
}

pub(super) fn is_expensive(program: &SafetyProgram) -> bool {
    program
        .next
        .iter()
        .flat_map(|branch| &branch.steps)
        .any(|step| match step {
            Step::Assign { value, .. } => !value.is_scalar_cost(),
            Step::Guard { expression } => !expression.is_scalar_cost(),
            Step::Frame { .. } | Step::Bind { .. } | Step::Choose { .. } => true,
        })
        || program
            .invariants
            .iter()
            .any(|predicate| !predicate.expression.is_scalar_cost())
}

impl Search<'_> {
    pub(super) fn parallel_frontier(
        &mut self,
        frontier: Range<usize>,
        workers: &mut Workers,
        arena: &mut Arena,
    ) -> Result<(), CoreError> {
        let mut start = frontier.start;
        while start < frontier.end {
            let active = workers
                .buffers
                .len()
                .min((frontier.end - start).div_ceil(8));
            let chunk = (frontier.end - start).div_ceil(active).min(workers.chunk);
            let end = (start + chunk * active).min(frontier.end);
            let ranges: Vec<_> = (start..end)
                .step_by(chunk)
                .map(|first| first..(first + chunk).min(end))
                .collect();
            let budget = WorkBudget::new(self.bounds.max_work - arena.work, ranges.len());
            let expansions: Vec<_> = workers.pool.install(|| {
                ranges
                    .into_par_iter()
                    .zip(workers.buffers.par_iter_mut())
                    .enumerate()
                    .map(|(worker, (range, buffer))| {
                        self.expand_range(range, arena, &budget, worker, buffer)
                    })
                    .collect()
            });
            arena.work += expansions.iter().map(|delta| delta.work).sum::<u32>();
            let candidates = workers
                .buffers
                .iter()
                .take(expansions.len())
                .map(|buffer| buffer.candidates.values.len() / self.store.width)
                .sum();
            workers.observe(end - start, candidates);
            for (delta, buffer) in expansions.into_iter().zip(&mut workers.buffers) {
                let mapping = arena.merge(delta)?;
                for value in buffer.candidates.values.iter_mut().flatten() {
                    *value = mapping.get(*value);
                }
                for event in buffer.candidates.events.drain(..) {
                    match event {
                        Event::Candidate {
                            parent,
                            action,
                            start,
                        } => {
                            self.accept(
                                &buffer.candidates.values[start..start + self.store.width],
                                Some(parent),
                                action,
                                arena,
                            )?;
                        }
                        Event::Deadlock(parent) => self.deadlock(parent, arena)?,
                        Event::Error(error) => return Err(error),
                    }
                    if self.stopped() {
                        return Ok(());
                    }
                }
            }
            start = end;
        }
        Ok(())
    }

    fn expand_range(
        &self,
        range: Range<usize>,
        base: &Arena,
        budget: &WorkBudget,
        worker: usize,
        buffer: &mut Buffer,
    ) -> ValueDelta {
        buffer.reset();
        let mut arena = base.fork(budget, worker);
        for parent in range {
            let current = self.store.state(parent);
            let mut enabled = false;
            for (action, branch) in self.program.next.iter().enumerate() {
                let result = visit_branch(
                    branch,
                    0,
                    EvalContext::new(current, &[]),
                    &mut buffer.next,
                    &mut arena,
                    &mut |values, _arena| {
                        enabled = true;
                        buffer.candidates.push(parent, action, values);
                        Ok(false)
                    },
                );
                match result {
                    Ok(true) => return arena.into_delta(),
                    Ok(false) => {}
                    Err(error) => {
                        buffer.candidates.events.push(Event::Error(error));
                        return arena.into_delta();
                    }
                }
            }
            if !enabled && self.program.check_deadlock {
                buffer.candidates.events.push(Event::Deadlock(parent));
                break;
            }
        }
        arena.into_delta()
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn candidates_keep_snapshots_and_order_when_buffers_are_reused() {
        let mut buffer = Candidates::default();
        let mut values = [Some(Scalar::Int(1)), Some(Scalar::Int(2))];
        buffer.push(3, 0, &values);
        values[0] = Some(Scalar::Int(7));
        buffer.push(4, 1, &values);
        assert_eq!(
            buffer.values,
            [
                Some(Scalar::Int(1)),
                Some(Scalar::Int(2)),
                Some(Scalar::Int(7)),
                Some(Scalar::Int(2))
            ]
        );
        for (event, expected) in buffer.events.iter().zip([(3, 0, 0), (4, 1, 2)]) {
            let Event::Candidate {
                parent,
                action,
                start,
                ..
            } = event
            else {
                panic!("expected candidate")
            };
            assert_eq!((*parent, *action, *start), expected);
        }
        buffer.clear();
        buffer.push(5, 2, &values);
        assert_eq!(buffer.values, values);
        assert_eq!(buffer.events.len(), 1);
    }
}

#[cfg(test)]
mod schedule_tests {
    use super::*;

    #[test]
    fn batch_tracks_fanout_and_stays_bounded() {
        let mut workers = Workers::new(2, 1).unwrap();
        assert_eq!(workers.chunk, 64);
        workers.observe(64, 2048);
        assert_eq!(workers.chunk, 32);
        workers.observe(64, 1);
        assert_eq!(workers.chunk, 128);
        workers.observe(64, 100_000);
        assert_eq!(workers.chunk, 16);
        workers.observe(64, 0);
        assert_eq!(workers.chunk, 128);
    }
}
